INSERT INTO public.news_articles VALUES ('6cda656b-e446-4fd5-9964-47b09179b2f4', 'https://vnexpress.net/trieu-cuong-vuot-bao-dong-3-duong-tran-xuan-soan-ngap-sau-4791234.html', 'Triều cường vượt báo động 3, đường Trần Xuân Soạn ngập sâu gần nửa mét', 'Chiều nay, triều cường vùng hạ lưu sông Sài Gòn - Đồng Nai dâng cao nhanh chóng. Ghi nhận tại đường Trần Xuân Soạn (Quận 7), từ 16h30 nước bắt đầu tràn qua mép bờ kè và dâng ngập đoạn dài hơn 1km. Nhiều đoạn nước sâu ngang đầu gối, phương tiện qua lại gặp vô vàn khó khăn.', '2026-10-01 06:10:12.76+00', true, '{"cause": "high_tide", "source": "VnExpress", "summary": "Đỉnh triều cường trên kênh Tẻ dâng cao 1.72m làm tràn bờ kè đường Trần Xuân Soạn, nước ngập sâu 45cm khiến hàng loạt xe máy chết máy.", "extractedLocations": [{"lat": 10.7485, "lng": 106.7082, "cause": "high_tide", "depthCm": 45, "district": "Quận 7", "streetName": "Trần Xuân Soạn"}]}', '2026-10-01 06:40:12.761+00');
INSERT INTO public.news_articles VALUES ('30b430d5-dcd3-4a38-88e9-21cfafc781d6', 'https://tuoitre.vn/nuoc-dang-cao-gio-tan-tam-nam-sai-gon-20260929112233.htm', 'Nước dâng cao giờ tan tầm trên đường Nguyễn Thị Thập và Huỳnh Tấn Phát', 'Đến 17h, khu vực ngã ba Nguyễn Thị Thập - Nguyễn Hữu Thọ nước ngập lênh láng. Nhiều phụ huynh đón con tan học phải dắt xe lội bì bõm qua làn nước đục. Lực lượng cứu hộ và CSGT đã có mặt tại hiện trường để phân luồng giao thông.', '2026-10-01 02:10:12.761+00', true, '{"cause": "combined", "source": "Tuổi Trẻ", "summary": "Triều cường kết hợp lưu lượng mưa cuối chiều khiến đường Nguyễn Thị Thập ngập 40cm, Huỳnh Tấn Phát ngập cục bộ 50cm.", "extractedLocations": [{"lat": 10.739, "lng": 106.696, "cause": "combined", "depthCm": 40, "district": "Quận 7", "streetName": "Nguyễn Thị Thập"}, {"lat": 10.7349, "lng": 106.7325, "cause": "high_tide", "depthCm": 50, "district": "Quận 7", "streetName": "Huỳnh Tấn Phát"}]}', '2026-10-01 03:10:12.761+00');
INSERT INTO public.news_articles VALUES ('1500a182-b886-42d5-9e85-eca34e20ba52', 'https://thanhnien.vn/song-sai-gon-tran-bo-thao-dien-bi-bom-trong-gio-cao-diem-185240928.htm', 'Sông Sài Gòn tràn bờ, Thảo Điền bì bõm nước ngập trong giờ cao điểm', 'Tại "khu nhà giàu" Thảo Điền (TP. Thủ Đức), tuyến đường Quốc Hương ngập sâu suốt đoạn dài hơn 500m. Người dân sống ven đường phải dùng bao cát và tấm chắn để ngăn sóng nước từ ô tô đánh vào nhà.', '2026-09-30 14:10:12.761+00', true, '{"cause": "high_tide", "source": "Thanh Niên", "summary": "Đường Quốc Hương tại Thảo Điền ngập lút bánh xe máy, độ sâu xấp xỉ 40cm do triều cường sông Sài Gòn dâng nhanh.", "extractedLocations": [{"lat": 10.8038, "lng": 106.7326, "cause": "high_tide", "depthCm": 40, "district": "TP. Thủ Đức", "streetName": "Quốc Hương"}]}', '2026-09-30 15:10:12.761+00');
INSERT INTO public.news_articles VALUES ('c9542b6c-beaa-464f-a9d5-61eb421f7457', 'https://dantri.com.vn/xa-hoi/mua-dong-cuc-lon-nguyen-van-qua-chim-trong-bien-nuoc-20260928.htm', 'Mưa dông cực lớn trút xuống cuối chiều, đường Nguyễn Văn Quá chìm trong biển nước', 'Hệ thống thoát nước quá tải sau cơn mưa lượng mưa đo được hơn 80mm. Đoạn qua chợ Cầu chìm sâu trong biển nước, nhiều xe máy chết máy la liệt dọc hai bên vỉa hè.', '2026-09-30 06:10:12.761+00', true, '{"cause": "heavy_rain", "source": "Dân Trí", "summary": "Cơn mưa lớn kéo dài 45 phút khiến đường Nguyễn Văn Quá (Quận 12) ngập sâu 50cm, giao thông tê liệt hoàn toàn.", "extractedLocations": [{"lat": 10.8415, "lng": 106.6273, "cause": "heavy_rain", "depthCm": 50, "district": "Quận 12", "streetName": "Nguyễn Văn Quá"}]}', '2026-09-30 08:10:12.761+00');
INSERT INTO public.news_articles VALUES ('1798822f-a258-45e8-9619-8f7a5f87f9c2', 'https://vnexpress.net/sap-cong-chao-o-tp-hcm-trong-mua-lon-5127346.html', 'Sập cổng chào ở TP HCM trong mưa lớn', 'Mưa lớn kèm gió mạnh khiến cổng chào bằng thép ở phường Bình Dương gãy, đổ xuống đường, gây ùn tắc giao thông tối 1/10.
INSERT INTO public.news_articles VALUES ('f1b17498-db06-4c86-ac80-bf719f70342f', 'https://vnexpress.net/tp-hcm-tiep-tuc-mua-lon-den-ngay-6-10-5127044.html', 'TP HCM tiếp tục mưa lớn đến ngày 6/10', 'TP HCM tiếp tục có mưa lớn vào chiều tối những ngày tới, tăng cả diện và lượng vào ngày 5-6/10, nguy cơ gây ngập vùng trũng thấp.
INSERT INTO public.news_articles VALUES ('839e5557-02a0-4974-8223-504a050936e8', 'https://vnexpress.net/khu-dan-cu-tp-hcm-van-ngap-sau-sau-15-tieng-5126949.html', 'Khu dân cư TP HCM vẫn ngập sâu sau 15 tiếng', 'Sáng 1/10, hơn 15 tiếng sau trận mưa lớn, hàng trăm hộ ở phường Thủ Đức vẫn chịu cảnh ngập gần nửa mét, sinh hoạt đảo lộn.
INSERT INTO public.news_articles VALUES ('2b0d53f1-dd70-491e-94e3-79f36b192556', 'https://vnexpress.net/duong-phan-huy-ich-ngap-hon-mot-met-lien-quan-thi-cong-kenh-tham-luong-5126954.html', 'Đường Phan Huy Ích ngập hơn một mét liên quan thi công kênh Tham Lương', 'TP HCMMưa lớn kết hợp triều cường chiều 30/9, trong khi thi công kênh Tham Lương thu hẹp dòng chảy, khiến đường Phan Huy Ích ngập hơn một mét, nước tràn vào xe buýt, nhà dân.
INSERT INTO public.news_articles VALUES ('69e5502f-4ac6-4ca8-a23b-4b9976a2dffb', 'https://tuoitre.vn/sam-chop-lien-hoi-trong-nhung-con-mua-tai-tphcm-do-dau-100261002072058442.htm', 'Sấm chớp liên hồi trong những cơn mưa tại TP.HCM do đâu?', 'Sấm chớp liên hồi, thậm chí có sét giáng xuống mặt đất tại khu vực TP.HCM - Ảnh: MXH
INSERT INTO public.news_articles VALUES ('974c0fae-59ff-48b1-b109-de3cc723fe61', 'https://vnexpress.net/nuoc-tran-vao-xe-buyt-hang-quan-sau-mua-lon-o-tp-hcm-5126823.html', 'Nước tràn vào xe buýt, hàng quán sau mưa lớn ở TP HCM', 'Trận mưa lớn suốt hai giờ khiến đường Phan Huy Ích ngập sâu hơn một mét, nước tràn vào xe buýt, hàng quán, nhiều phương tiện chết máy, tối 30/9.
INSERT INTO public.news_articles VALUES ('d3a0528e-9e14-4040-bd92-3206bfbbb36d', 'https://vnexpress.net/mua-lon-gay-ngap-ket-xe-khap-tp-hcm-5126477.html', 'Mưa lớn gây ngập, kẹt xe khắp TP HCM', 'Mưa trút xuống trong gần hai giờ, đúng lúc người dân đi làm, đến trường, khiến nhiều tuyến đường TP HCM ngập, dòng xe ùn ứ kéo dài, sáng 30/9.
INSERT INTO public.news_articles VALUES ('7e46b7f3-b807-44cf-8041-7b6c2f89654f', 'https://tuoitre.vn/se-khoi-thong-dong-chay-de-giam-ngap-khu-dan-cu-o-phuong-binh-tri-dong-100261001165735653.htm', 'Sẽ khơi thông dòng chảy để giảm ngập khu dân cư ở phường Bình Trị Đông', 'UBND phường Bình Trị Đông sẽ tiếp tục thực hiện các biện pháp để giảm ngập khu vực - Ảnh: NGỌC LÂN
INSERT INTO public.news_articles VALUES ('ea986028-83cd-464b-83d1-0baca5869c8f', 'https://tuoitre.vn/csgt-tphcm-khuyen-cao-nguoi-di-xe-may-di-cham-nhin-ky-dung-co-vuot-ngap-sau-100261003122021889.htm', 'CSGT TP.HCM khuyến cáo người đi xe máy: Đi chậm, nhìn kỹ, đừng cố vượt ngập sâu', 'Cảnh sát giao thông TP.HCM phân luồng giao thông trong lúc nước ngập - Ảnh: PC08
INSERT INTO public.news_articles VALUES ('11ba86f6-d09b-4c95-afdc-77c7a401ea0a', 'https://vnexpress.net/gan-4-000-tia-set-giang-xuong-tp-hcm-trong-hai-ngay-mua-lon-5127815.html', 'Gần 4.000 tia sét giáng xuống TP HCM trong hai ngày mưa lớn', 'Ngày 30/9 và 1/10, TP HCM hứng 3.810 cú sét, hơn 2.000 tia giáng xuống mặt đất, nằm trong những ngày có sét nhiều nhất gần hai năm qua, theo Cục Khí tượng Thủy văn.
INSERT INTO public.news_articles VALUES ('dc4b3971-612a-4940-8abd-3c83e14f02e0', 'https://thanhnien.vn/so-xay-dung-tphcm-giai-trinh-nguyen-nhan-ngap-185261002223854863.htm', 'Sở Xây dựng TP.HCM giải trình nguyên nhân ngập', 'Tại buổi tiếp xúc, một số cử tri phản ánh tình trạng nhiều tuyến đường, khu dân cư ngập nặng khi mưa lớn hoặc triều cường, trong lúc TP.HCM triển khai nhiều chương trình chống ngập; việc chống ngập còn cục bộ, chắp vá; có nơi khắc phục điểm ngập này lại phát sinh ngập nơi khác; việc nâng đường, làm ...', '2026-10-02 22:53:00+00', true, '{"cause": "combined", "source": "Thanh Niên", "summary": "Mưa lớn kết hợp triều cường và việc thi công các dự án hạ tầng (như cải tạo kênh Tham Lương - Bến Cát - rạch Nước Lên và đường Vành đai 2) gây ngập nặng tại một số khu vực thuộc đường Phan Huy Ích (Quận Gò Vấp) và đường số 11 (TP. Thủ Đức) vào cuối tháng 9 và đầu tháng 10 năm 2024.", "extractedLocations": [{"lat": 10.825283598214686, "lng": 106.62912012811788, "cause": "combined", "depthCm": 30, "district": "Quận Gò Vấp", "streetName": "Hẻm 15 Phan Huy Ích"}, {"lat": 10.75, "lng": 106.7, "cause": "combined", "depthCm": 20, "district": "Quận Gò Vấp", "streetName": "Hẻm 51 Phan Huy Ích"}, {"lat": 10.875824563807514, "lng": 106.8222123533858, "cause": "combined", "depthCm": 50, "district": "Thành phố Thủ Đức", "streetName": "Đường số 11"}]}', '2026-10-03 08:03:53.431+00');
INSERT INTO public.news_articles VALUES ('abf55470-f0a8-4f31-9209-f9244fb762b5', 'https://vnexpress.net/tp-hcm-dung-may-bom-di-dong-xu-ly-cac-diem-ngap-sau-5127770.html', 'TP HCM dùng máy bơm di động xử lý các điểm ngập sâu', 'Cảnh sát PCCC TP HCM sẽ bố trí máy bơm di động xử lý các điểm ngập sâu, kết hợp điều tiết giao thông để bảo đảm an toàn khi mưa lớn, triều cường.
